// @ts-nocheck -- desktop bridge additions are generated by Electron preload.
import {useEffect,useState} from 'react';

export interface PersonalMonitor{id:string;slug:string;name:string;sourceType:'main'|'stage'|'livestream';layout:'mirror'|'current-next';defaultLanguage:'de'|'en';showCurrent:boolean;showNext:boolean;showClock:boolean;showCountdown:boolean;showNotes:boolean;showOrderOfService:boolean;enabled:boolean;connected?:number}
export interface RemoteDevice{id:string;name:string;permissionRole:'view'|'preacher'|'control'|'advanced';preferredLanguage:'de'|'en';permissions:string[];token:string;revoked:boolean;lastSeenAt?:string}
export interface RemoteServiceState{active:boolean;address:string;port:number;monitors:PersonalMonitor[];remotes:RemoteDevice[]}
const empty:RemoteServiceState={active:false,address:'127.0.0.1',port:43170,monitors:[],remotes:[]};
const rolePermissions:Record<RemoteDevice['permissionRole'],string[]>={view:['remote.view'],preacher:['remote.view','remote.viewNotes'],control:['remote.view','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen'],advanced:['remote.view','remote.viewNotes','remote.next','remote.previous','remote.selectSlide','remote.selectItem','remote.quickScreen','remote.stageMessage','remote.viewRecording']};

export function RemoteCenter(){
  const [state,setState]=useState(empty),[mode,setMode]=useState<'overview'|'monitor'|'remote'>('overview'),[name,setName]=useState('Prediger Monitor'),[slug,setSlug]=useState('prediger'),[source,setSource]=useState<PersonalMonitor['sourceType']>('stage'),[role,setRole]=useState<RemoteDevice['permissionRole']>('preacher'),[language,setLanguage]=useState<'de'|'en'>('de');
  const refresh=()=>void window.desktop?.remote.get().then(setState);
  useEffect(()=>{refresh()},[]);
  const base=`http://${state.address}:${state.port}`;
  async function addMonitor(){await window.desktop?.remote.saveMonitor({id:crypto.randomUUID(),slug:slug.toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/^-+|-+$/g,''),name,sourceType:source,layout:'current-next',defaultLanguage:language,showCurrent:true,showNext:true,showClock:true,showCountdown:true,showNotes:false,showOrderOfService:false,enabled:true});setMode('overview');refresh()}
  async function addRemote(){const result=await window.desktop?.remote.createSession({name,permissionRole:role,preferredLanguage:language,permissions:rolePermissions[role]});setMode('overview');await refresh();if(result)await navigator.clipboard.writeText(`${base}/remote/${result.token}`)}
  const copy=(value:string)=>void navigator.clipboard.writeText(value);
  return <section className="remote-center"><h3>Anzeige &amp; Web-Steuerung</h3><p>Personal Monitore sind dauerhaft erreichbare, reine Anzeigen. Web-Steuerungen erhalten eine individuelle widerrufbare Sitzung und nur ausdrücklich freigegebene Befehle.</p><div className={`remote-service ${state.active?'online':'offline'}`}><span/><div><b>{state.active?'Remote-Service bereit':'Remote-Service nicht verfügbar'}</b><small>{base} · lokales Netzwerk</small></div><button onClick={refresh}>STATUS PRÜFEN</button></div>{mode==='overview'?<><div className="remote-actions"><button className="primary" onClick={()=>{setName('Prediger Monitor');setSlug('prediger');setMode('monitor')}}>+ PERSONAL MONITOR</button><button onClick={()=>{setName('iPad Prediger');setMode('remote')}}>+ GERÄT VERBINDEN</button></div><h4>PERSONAL MONITORE</h4><div className="remote-list">{state.monitors.map(m=><article key={m.id}><span className="material-symbols-outlined">monitor</span><div><b>{m.name}</b><small>{m.sourceType.toUpperCase()} · /monitor/{m.slug} · {m.connected??0} verbunden</small></div><button onClick={()=>copy(`${base}/monitor/${m.slug}`)}>URL KOPIEREN</button><button onClick={()=>void window.desktop?.openExternal(`${base}/monitor/${m.slug}`)}>VORSCHAU</button><button className="danger" onClick={async()=>{if(confirm(`Personal Monitor „${m.name}“ deaktivieren?`)){await window.desktop?.remote.removeMonitor(m.id);refresh()}}}>DEAKTIVIEREN</button></article>)||null}{!state.monitors.length&&<p>Noch kein Personal Monitor eingerichtet.</p>}</div><h4>WEB-STEUERUNGEN</h4><div className="remote-list">{state.remotes.filter(r=>!r.revoked).map(r=><article key={r.id}><span className="material-symbols-outlined">phone_iphone</span><div><b>{r.name}</b><small>{r.permissionRole.toUpperCase()} · {r.preferredLanguage==='de'?'Deutsch':'English'} · sichere Einzelsitzung</small></div><button onClick={()=>copy(`${base}/remote/${r.token}`)}>LINK KOPIEREN</button><button className="danger" onClick={async()=>{await window.desktop?.remote.revokeSession(r.id);refresh()}}>ZUGRIFF WIDERRUFEN</button></article>)}{!state.remotes.some(r=>!r.revoked)&&<p>Noch keine Web-Steuerung freigegeben.</p>}</div></>:mode==='monitor'?<div className="remote-form"><h4>PERSONAL MONITOR ERSTELLEN</h4><label>Name<input value={name} onChange={e=>setName(e.target.value)}/></label><label>URL-Kennung<input value={slug} onChange={e=>setSlug(e.target.value)}/><small>Die URL bleibt bei Gottesdienst-, Benutzer- und Programmwechsel gleich.</small></label><label>Quelle<select value={source} onChange={e=>setSource(e.target.value as PersonalMonitor['sourceType'])}><option value="stage">STAGE – Prediger</option><option value="main">MAIN</option><option value="livestream">LIVESTREAM</option></select></label><label>Sprache<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">Deutsch</option><option value="en">English</option></select></label><footer><button onClick={()=>setMode('overview')}>ABBRECHEN</button><button className="primary" disabled={!name.trim()||!slug.trim()} onClick={()=>void addMonitor()}>ERSTELLEN</button></footer></div>:<div className="remote-form"><h4>WEB-STEUERUNG FREIGEBEN</h4><label>Gerätename<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Berechtigung<select value={role} onChange={e=>setRole(e.target.value as RemoteDevice['permissionRole'])}><option value="view">Nur Anzeige</option><option value="preacher">Prediger</option><option value="control">Steuerung</option><option value="advanced">Erweiterte Steuerung</option></select></label><label>Sprache<select value={language} onChange={e=>setLanguage(e.target.value as 'de'|'en')}><option value="de">Deutsch</option><option value="en">English</option></select></label><p>Der individuelle Link wird nach dem Erstellen in die Zwischenablage kopiert. ON AIR/OFF AIR bleibt auch bei erweiterter Steuerung gesperrt.</p><footer><button onClick={()=>setMode('overview')}>ABBRECHEN</button><button className="primary" disabled={!name.trim()} onClick={()=>void addRemote()}>VERBINDUNG STARTEN</button></footer></div>}</section>
}
